import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Mail, Lock, Eye, EyeOff, AlertCircle } from 'lucide-react';
import InputField from './InputField';
import AuthLayout from './AuthLayout';

const Login = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    rememberMe: false,
  });

  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loginError, setLoginError] = useState('');

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));

    // Clear errors when user starts typing
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: '' }));
    }
    if (loginError) setLoginError('');
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.email.trim()) {
      newErrors.email = "L'email est requis";
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = "L'email est invalide";
    }

    if (!formData.password) {
      newErrors.password = 'Le mot de passe est requis';
    }

    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const validationErrors = validateForm();
    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors);
      return;
    }

    setIsSubmitting(true);
    setLoginError('');

    // Simuler une requête API
    setTimeout(() => {
      // Simulation de connexion réussie
      if (formData.email === 'enzo@gmail.com' && formData.password === '41329758@#Enzo') {
        console.log('Connexion réussie:', formData);

        // Sauvegarder l'état de connexion
        localStorage.setItem('isAuthenticated', 'true');
        localStorage.setItem('userEmail', formData.email);
        if (formData.rememberMe) {
          localStorage.setItem('rememberMe', 'true');
        }

        // Rediriger vers le dashboard
        navigate('/dashboard');
      } else {
        // Simulation d'échec
        setLoginError('Email ou mot de passe incorrect');
      }
      setIsSubmitting(false);
    }, 1500);
  };

  const handleForgotPassword = () => {
    navigate('/forgot-password');
  };

  return (
    <AuthLayout
      title="Content de vous revoir"
      subtitle="Connectez-vous à votre compte pour continuer."
      type="login"
    >
      <form onSubmit={handleSubmit}>
        {loginError && (
          <div className="mb-6 p-4 rounded-lg bg-red-50 dark:bg-red-900/30 border border-red-200 dark:border-red-800">
            <div className="flex items-center">
              <AlertCircle className="text-red-600 dark:text-red-400 mr-2" size={20} />
              <span className="text-red-700 dark:text-red-300 font-medium">
                {loginError}
              </span>
            </div>
          </div>
        )}

        {/* Demo credentials */}
        <div className="mb-6 p-4 rounded-lg bg-primary-50 dark:bg-primary-900/20 border border-primary-200 dark:border-primary-800">
          <h4 className="font-semibold text-primary-800 dark:text-primary-300 mb-2">
            🔐 Identifiants de démonstration
          </h4>
          <div className="text-sm text-primary-700 dark:text-primary-400 space-y-1">
            <p>Email: <span className="font-mono">demo@exemple.com</span></p>
            <p>Mot de passe: <span className="font-mono">Demo123!</span></p>
          </div>
        </div>

        <InputField
          label="Adresse email"
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          placeholder="vous@exemple.com"
          error={errors.email}
          icon={Mail}
          required
        />

        <InputField
          label="Mot de passe"
          type="password"
          name="password"
          value={formData.password}
          onChange={handleChange}
          placeholder="Votre mot de passe"
          error={errors.password}
          icon={Lock}
          required
          showPassword={showPassword}
          onTogglePassword={() => setShowPassword(!showPassword)}
        />

        {/* Options */}
        <div className="flex items-center justify-between mb-6">
          <label className="flex items-center space-x-3 cursor-pointer">
            <div className="relative">
              <input
                type="checkbox"
                name="rememberMe"
                checked={formData.rememberMe}
                onChange={handleChange}
                className="absolute opacity-0 w-0 h-0"
                id="rememberMe"
              />
              <div className={`
                w-5 h-5 rounded border flex items-center justify-center
                ${formData.rememberMe 
                  ? 'bg-primary-600 border-primary-600' 
                  : 'border-neutral-300 dark:border-neutral-700'
                }
                transition-colors duration-200
              `}>
                {formData.rememberMe && (
                  <div className="w-2 h-2 bg-white rounded-sm"></div>
                )}
              </div>
            </div>
            <span className="text-sm text-neutral-700 dark:text-neutral-300">
              Se souvenir de moi
            </span>
          </label>

          <button
            type="button"
            onClick={handleForgotPassword}
            className="text-sm text-primary-600 dark:text-primary-400 hover:underline font-medium"
          >
            Mot de passe oublié ?
          </button>
        </div>

        {/* Submit button */}
        <button
          type="submit"
          disabled={isSubmitting}
          className={`
            w-full py-3.5 px-4 rounded-lg font-semibold
            ${isSubmitting 
              ? 'bg-primary-400 cursor-not-allowed' 
              : 'bg-primary-600 hover:bg-primary-700'
            }
            text-white
            focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2
            transition-all duration-200
            transform hover:scale-[1.02] active:scale-[0.98]
            shadow-lg hover:shadow-xl
            mb-6
          `}
        >
          {isSubmitting ? (
            <div className="flex items-center justify-center">
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
              Connexion en cours...
            </div>
          ) : (
            "Se connecter"
          )}
        </button>

        {/* Quick login options */}
        <div className="text-center mb-6">
          <p className="text-sm text-neutral-600 dark:text-neutral-400 mb-3">
            Se connecter rapidement avec :
          </p>
          <div className="flex justify-center space-x-4">
            <button
              type="button"
              className="p-3 rounded-full bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 hover:bg-neutral-50 dark:hover:bg-neutral-700 shadow-sm"
              onClick={() => {
                setFormData({
                  email: 'demo@exemple.com',
                  password: 'Demo123!',
                  rememberMe: true
                });
              }}
            >
              <span className="text-xs font-medium">Démo</span>
            </button>
            <button
              type="button"
              className="p-3 rounded-full bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 hover:bg-neutral-50 dark:hover:bg-neutral-700 shadow-sm"
              onClick={() => {
                setFormData({
                  email: 'admin@exemple.com',
                  password: 'Admin123!',
                  rememberMe: false
                });
              }}
            >
              <span className="text-xs font-medium">Admin</span>
            </button>
            <button
              type="button"
              className="p-3 rounded-full bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 hover:bg-neutral-50 dark:hover:bg-neutral-700 shadow-sm"
              onClick={() => {
                setFormData({
                  email: 'user@exemple.com',
                  password: 'User123!',
                  rememberMe: false
                });
              }}
            >
              <span className="text-xs font-medium">Utilisateur</span>
            </button>
          </div>
        </div>
      </form>
    </AuthLayout>
  );
};

export default Login;
